<template>
    <header id="top-bar" :class="{ dark: isDark }" class="min-h-[6rem] flex items-center">
        <div class="container">
            <a class="navbar-brand" href="/">
                <img src="@/assets/logo2.png" alt="Logo G. Brandão" width="100" />
            </a>

            <!-- Botão Hambúrguer, só visível em mobile -->
            <button class="btn-hamburger" @click="toggleMenu" aria-label="Toggle Menu">
                <span :class="{ 'bar': true, 'open': menuOpen }"></span>
                <span :class="{ 'bar': true, 'open': menuOpen }"></span>
                <span :class="{ 'bar': true, 'open': menuOpen }"></span>
            </button>

            <nav :class="['nav', { open: menuOpen }]">
                <ul class="nav-list">
                    <li class="nav-item" :class="{ active: activeSection === 'home' }">
                        <a href="#home" @click.prevent="scrollToTop">{{ $t('topMenu.home') }}</a>
                    </li>
                    <li class="nav-item" :class="{ active: activeSection === 'skills' }">
                        <a href="#skills" @click.prevent="scrollToSection('skills')">{{ $t('topMenu.skills') }}</a>
                    </li>
                    <li class="nav-item" :class="{ active: activeSection === 'projects' }">
                        <a href="#projects" @click.prevent="scrollToSection('projects')">{{ $t('topMenu.projects')
                            }}</a>
                    </li>
                    <li class="nav-item" :class="{ active: activeSection === 'experience' }">
                        <a href="#experienceTimeline" @click.prevent="scrollToSection('experienceTimeline')">{{
                            $t('topMenu.experience') }}</a>
                    </li>
                    <li class="nav-item" :class="{ active: activeSection === 'contact' }">
                        <a href="#contact" @click.prevent="scrollToSection('contact')">{{ $t('topMenu.contact') }}</a>
                    </li>

                </ul>
                <div class="controls">
                    <button @click="toggleLanguage" class="btn-lang">
                        <font-awesome-icon icon="globe" /> {{ currentLang.toUpperCase() }}
                    </button>
                </div>
            </nav>
        </div>
    </header>
</template>


<script setup>
import { useI18n } from 'vue-i18n'
import { ref, onMounted, onBeforeUnmount, onUnmounted } from 'vue'

const isDark = ref(false)
const { locale } = useI18n()
const currentLang = ref(locale.value)

const menuOpen = ref(false)

function toggleLanguage() {
    currentLang.value = currentLang.value === 'pt' ? 'en' : 'pt'
    locale.value = currentLang.value
    localStorage.setItem('lang', currentLang.value)
}

const scrollToTop = () => {
    window.scrollTo({
        top: 0,
        behavior: 'smooth',
    })
    closeMenu()
}

const activeSection = ref('home')

const observeSections = () => {
    const options = {
        root: null,
        rootMargin: '0px',
        threshold: 0.6,
    }

    const observer = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
            if (entry.isIntersecting) {
                activeSection.value = entry.target.id
            }
        })
    }, options)

    document.querySelectorAll('section').forEach((section) => {
        observer.observe(section)
    })

    return observer
}

let observer

const handleScroll = () => {
    const topBar = document.getElementById('top-bar')
    if (window.scrollY > 100) {
        topBar.classList.add('scrolled')
    } else {
        topBar.classList.remove('scrolled')
    }
}

const scrollToSection = (id) => {
    const target = document.getElementById(id)
    if (!target) return

    const offset = 150
    const topPosition = target.getBoundingClientRect().top + window.scrollY - offset

    window.scrollTo({
        top: topPosition,
        behavior: 'smooth',
    })

    closeMenu()
}


const toggleMenu = () => {
    menuOpen.value = !menuOpen.value
}

const closeMenu = () => {
    menuOpen.value = false
}

onMounted(() => {
    const savedLang = localStorage.getItem('lang') || 'pt'
    locale.value = savedLang
    currentLang.value = savedLang
    observer = observeSections()

    const savedTheme = localStorage.getItem('theme')
    isDark.value = savedTheme === 'dark'
    if (isDark.value) {
        document.documentElement.classList.add('dark')
    } else {
        document.documentElement.classList.remove('dark')
    }
    window.addEventListener('scroll', handleScroll)
})

onBeforeUnmount(() => {
    window.removeEventListener('scroll', handleScroll)
})

onUnmounted(() => {
    if (observer) observer.disconnect()
})
</script>


<style scoped lang="scss">
@import '@/assets/sass/styles.scss';

#top-bar {
    @apply fixed top-0 left-0 w-full z-[1000] py-4 backdrop-blur transition-colors duration-300;
    background: transparent;


    &.scrolled {
        background-color: rgba(28, 27, 26, 0.5);
    }

    .container {
        @apply max-w-[1200px] mx-auto flex justify-between items-center px-4;
    }


    .navbar-brand img {
        @apply max-w-[100px] h-auto;
    }


    /* Botão hamburguer - só no mobile */
    .btn-hamburger {
        @apply hidden flex-col justify-around w-7 h-[22px] bg-transparent border-none cursor-pointer p-0 z-[1100];

        .bar {
            @apply w-full h-0.5 rounded-sm transition-all duration-300 ease-linear relative;
            background-color: $dark-text-primary;
        }

        .bar.open:nth-child(1) {
            @apply relative;
            transform: rotate(45deg);
            top: 8px;
        }

        .bar.open:nth-child(2) {
            @apply opacity-0;
        }

        .bar.open:nth-child(3) {
            @apply relative;
            transform: rotate(-45deg);
            top: -8px;
        }

    }

    .nav {
        @apply flex items-center gap-12;


        .nav-list {
            @apply flex list-none p-0 m-0 gap-12;


            .nav-item {
                @apply w-[85px] text-center font-semibold;


                a {
                    text-decoration: none;
                    font-weight: bold;
                    transition: color 0.3s ease;
                    color: $dark-text-primary;

                    &:hover {
                        color: $dark-secondary;
                        transition: color 0.2s ease;
                    }
                }

                &.active {
                    a {
                        color: $light-secondary;
                        border-bottom: 2px solid $light-secondary;
                    }
                }
            }
        }

        .controls {
            @apply flex gap-12;

            .btn-lang {
                @apply bg-none border-none py-1.5 px-4 rounded-md cursor-pointer font-bold transition-all duration-300 ease-in-out;

                color: $dark-text-primary;

                &:hover {
                    background-color: lighten($dark-button-hover, 10%);
                }
            }
        }
    }

    /* ===== Responsividade ===== */
    @media (max-width: 768px) {
        padding: 0.5rem 0;

        .btn-hamburger {
            display: flex;
        }

        .nav {
            position: fixed;
            top: 6rem;
            right: 0;
            width: 240px;
            height: calc(100vh - 6rem);
            backdrop-filter: blur(15px);
            flex-direction: column;
            gap: 1.5rem;
            padding: 1.5rem;
            transform: translateX(100%);
            transition: transform 0.3s ease;
            z-index: 1050;
            box-shadow: -2px 0 12px rgba(0, 0, 0, 0.25);
            background: $dark-primary;

            &.open {
                transform: translateX(0);
            }

            .nav-list {
                flex-direction: column;
                gap: 1rem;

                .nav-item {
                    width: 100%;
                    text-align: center;

                    a {
                        padding: 0.5rem 1rem;
                        width: 100%;
                        display: block;
                    }
                }
            }

            .controls {
                justify-content: flex-start;
                gap: 1rem;

                .btn-lang,
                .btn-theme {
                    padding: 0.4rem 1rem;
                }
            }
        }
    }
}
</style>
