<template>
    <section id="experienceTimeline" class="screen">
        <h2 class="section-title">{{ $t('experience.title') }}</h2>

        <!-- Timeline container -->
        <div class="relative mt-5">
            <div class="vertical-bar"></div>
            <div class="jobs-wrapper">
                <div v-for="(exp, index) in jobs" :key="index" class="job-item"
                    :class="index % 2 === 0 ? 'even' : 'odd'">
                    <div class="content">
                        <div class="card-experience">
                            <h3 class="text-xl font-semibold">{{ exp.title }}</h3>
                            <p class="text-sm text-[#E53935]">{{ exp.company }}</p>
                            <p class="text-sm text-[#BDBDBD] mb-4">{{ exp.period }}</p>
                            <p class="text-sm text-[#F5F5F5]" v-html="exp.description"></p>
                        </div>
                    </div>
                </div>
            </div>

        </div>
    </section>
</template>

<script setup>

import { computed } from 'vue'
import { useI18n } from 'vue-i18n'

const { locale, getLocaleMessage } = useI18n()
const jobs = computed(() => {
    const messages = getLocaleMessage(locale.value)
    return messages.experience.jobs || []
})
</script>

<style lang="scss">
@import '@/assets/sass/styles.scss';

#experienceTimeline {
    background: linear-gradient(to bottom, $dark-secondary 10%, $dark-primary 80%);
    color: $dark-text-primary;
    @apply py-1 px-10 md:px-40;

    .vertical-bar {
        border-left: 2px solid $light-border;
        @apply absolute left-1/2 -translate-x-1/2 h-full md:block hidden;
    }

    .vertical-bar-divider {
        background-color: $dark-accent-red;
        border: 2px solid $dark-primary;
        @apply w-4 h-4 rounded-full absolute left-1/2 -translate-x-1/2 mt-2 md:mx-0;
    }

    .card-experience {
        background-color: $dark-primary;
        border: 1px solid $dark-border;
        @apply p-6 rounded-xl;
    }

    .jobs-wrapper {
        @apply relative;

        .job-item {
            @apply relative flex flex-col items-start mb-4 md:flex-row;

            &.even {
                @apply md:flex-row;
            }

            &.odd {
                @apply md:flex-row-reverse;
            }

            .content {
                @apply w-full px-0 pb-6 md:w-1/2 md:px-8 md:pb-0;
            }

            .divider {
                @apply w-full h-4 relative flex justify-center md:w-8 md:h-auto;

                &::before {
                    content: '';
                    background-color: $dark-accent-red;
                    @apply absolute left-1/2 top-0 -translate-x-1/2 w-1 h-full rounded md:hidden;
                }
            }
        }
    }
}
</style>
